const teachingPlans=[
{id:'waterfall',title:'瀑布怎样变成银河？',subtitle:'望庐山瀑布 · 李白',stages:['初中'],minutes:10,works:[['lb-lushan','望庐山瀑布（其二）']],sources:['lushan','goals'],goal:'能用动词、夸张与想象解释诗句如何超越眼前实景。',question:'同一处瀑布，照片能拍到的和诗人想出来的，有什么不同？',steps:[['先读，再画','2分钟','暂不播放影片。读四句诗，在纸上画四格草图；每格写一个画面依据。','四格草图＋四个原文关键词。'],['给动词做一次替换','3分钟','把“挂”试换为“流”，比较远望时的画面；再找出诗中从观景进入想象的词语。','两句话说明替换后失去的效果。'],['和影片商量，而非照单全收','3分钟','在庐山站点看实景或影片，列出“原文可支持”与“画面补充想象”各一项；不拿“三千尺”计算实测高度。','一张两栏证据表。'],['带着解释再读','2分钟','选择一处重音或停顿，并说明它怎样表现瀑布的气势；同桌听后反馈。','20秒朗读＋一条文本理由。']],check:['能以具体词语解释画面变化','能区分诗意想象、现代实景与影片补充','朗读处理有文本理由'],hint:'“挂”可从远望的整体感、静态造型切入；“飞流”又写出动势。“疑”引向想象。允许不同朗读方案，不设唯一重音。',extend:'高中延伸：比较本诗与《题西林壁》的观看位置和认识方式，避免只用“浪漫”给诗人贴标签。'},
{id:'spring-view',title:'春天为什么让人落泪？',subtitle:'春望 · 杜甫',stages:['初中'],minutes:12,works:[['df-chunwang','春望']],sources:['spring','reading','goals'],goal:'能结合处境与词句，解释春景与悲情的联系。',question:'如果删去题目和作者信息，哪些字仍能让你读出这不是一首单纯赞春的诗？',steps:[['两次读，保留疑问','3分钟','先按普通春景读，再读全诗，圈出令前一种读法发生变化的词。教师只补充写作时身陷长安的必要背景。','至少两处词语＋一个待解问题。'],['把大景与小动作连起来','4分钟','小组用“国事—亲人—自身”整理四联证据；这是一种整理方法，不要求每联只有一种情感。','三栏表，每栏至少一处诗句。'],['给朗读做一张提示卡','3分钟','任选一联，写出语速、停顿与重音，再用诗句说明理由；可重看影片的花鸟或家书场景，并指出其补充之处。','一张有证据的朗读提示卡。'],['一句话离堂','2分钟','补全：“表面上写……，因为……，我读出了……”。至少使用两个原文词。','一段40—60字的解释。']],check:['感受能回到两个以上原文词','能把家国、亲情和动作联系起来','没有把影片细节当成诗中明写的事实'],hint:'可从“破”“深”“溅泪”“惊心”“抵万金”“搔”进入。感时与恨别可以交织，不必强行把花鸟各锁定为唯一含义。',extend:'高中延伸：比较《登高》中的景物与身体感受，讨论情景关系的相同与不同。'},
{id:'red-cliff',title:'他在写周瑜，也在写谁？',subtitle:'念奴娇·赤壁怀古 · 苏轼',stages:['高中'],minutes:15,works:[['ss-nian','念奴娇·赤壁怀古']],sources:['reading','goals'],goal:'能用词中证据分析怀古人物与词人自我之间的关系，解释结尾的情感张力。',question:'如果“人生如梦”只有消沉一种意思，前文哪些地方会让这个解释变得不够？',steps:[['先听自己的声音','3分钟','独立朗读上片，给动词和声势词做标记；用一句话概括江景的力量，不先给出“豪放”的答案。','三个关键词＋一句概括。'],['画两列人物证据','5分钟','左列写词中周瑜的形象，右列写词中显出的自我感受；每列至少两处词句，再标出连接两者的转折。','人物证据对照表。'],['给导演提一条意见','4分钟','看周瑜和江月场景。指出一处由原文支持的表达，以及一处影片不能替你决定的解释；黄州地点与三国怀想分开说明。','一条导演建议＋一条解释边界。'],['用反证完善观点','3分钟','小组提出对结尾的理解，再找一句可能使观点复杂化的词；写出修订后的判断。','80字短评，含两处证据与一条保留意见。']],check:['把人物比较落实到具体词句','能说明情感转折，允许复杂或并存的感受','区分怀古想象、作者行迹与真实战场'],hint:'可讨论意气、功业、自我感慨以及面对江月的收束。不要用“完全旷达”或“纯粹消沉”替代论证，也不要把词中周瑜当成史传的逐条复写。',extend:'与《定风波》比较：同一作者面对处境时，语气、形象和表达策略怎样不同？'},
{id:'two-lushan',title:'同一座庐山，两种观看',subtitle:'李白 × 苏轼 · 比较阅读',stages:['初中','高中'],minutes:12,works:[['lb-lushan','望庐山瀑布（其二）'],['ss-xilin','题西林壁']],sources:['reading','goals'],goal:'能以观看位置与语言证据比较两首诗，而非只列作者标签。',question:'在地图上是同一个地点，在诗中为什么会变成两种问题？',steps:[['到同一处，读两首诗','3分钟','分别打开两位诗人的庐山站点。标出观看距离、位置或视角有关的词；地点相同不等于游览时间相同。','两组视角词语。'],['写一张比较表','5分钟','比较“看见了什么—怎样写—引出什么感受或思考”；每首至少找两处证据。','三项对照表。'],['一地两签','4分钟','为庐山写两张各40字的展签，一张突出想象，一张突出认识；同桌检查两签是否仍可互换。','两张不能随意互换的展签。']],check:['两首诗都有文本证据','能解释观看方式与表达的关系','比较不止于“一个浪漫、一个哲理”'],hint:'“遥看”“疑”与“横看”“侧”“远近高低”“身在”可作切入。展示照片只提供观察材料，不能证明古人精确站位。',extend:'高中可进一步讨论：两首诗如何从可见景物走向难以直接拍摄的内容？'},
{id:'river-voices',title:'一条江，三种声音',subtitle:'李白 × 杜甫 × 苏轼 · 议题阅读',stages:['高中'],minutes:15,works:[['lb-jingmen','渡荆门送别'],['df-denggao','登高'],['ss-nian','念奴娇·赤壁怀古']],sources:['reading','project'],goal:'能比较同类意象在不同文本中的作用，并把解释转化成简洁的推荐语。',question:'江水看起来都在流，诗中承载的时间和情感也一样吗？',steps:[['沿地图找三处江景','4分钟','每组认领一篇，标出相关地点、文本中的江水和一个情感转折。地理线索不能单独证明情感。','地点＋意象＋转折的三项记录。'],['互换证据卡','6分钟','三组交换关键词，比较江水与故乡、生命或历史的关系；有不同看法时先回到上下句。','一张三篇比较表。'],['给金句写推荐语','5分钟','选一处江景写60—80字推荐语，说明它为何不可用另一首的句子替代；标注引句和理由。','推荐语＋两项同伴反馈。']],check:['比较同类意象时保留各篇语境','能用证据解释差异','推荐语包含语言分析而非空泛赞美'],hint:'允许不同概括；“江水代表什么”不是固定符号填空。不要把写到的所有地点都算成作者亲历。',extend:'把三条推荐语组成一面班级“诗中江河”展墙，并注明各篇的系年与不确定性。'},
{id:'dongpo-label',title:'为黄州写一块人物展签',subtitle:'苏轼专题 · 从处境到表达',stages:['初中','高中'],minutes:15,works:[['ss-ding','定风波·莫听穿林打叶声'],['ss-nian','念奴娇·赤壁怀古'],['ss-chengtian','记承天寺夜游']],sources:['project','goals'],goal:'能据作品组织人物介绍，区分事实、文本表达与自己的评价。',question:'“苏轼很乐观”能说明黄州时期所有作品吗？',steps:[['选择适合学段的材料','4分钟','初中以《记承天寺夜游》为主，高中选《定风波》与《念奴娇》比较。在书架读原文，在地图确认黄州线索。','作品卡：篇名、地点、两处原文词句。'],['三种笔迹写展签','7分钟','用三栏分别记录“可核实的处境”“文本里的表达”“我的解释”，再写一段100字人物展签。','一块有证据的人物展签。'],['请同伴做策展审核','4分钟','检查展签是否把一种情绪说成了人物全部，是否有无法核实的细节；修改一处过满的判断。','修订稿＋一条修改理由。']],check:['人物判断有作品支撑','事实与解释没有混写','能保留同一作者的不同情感面向'],hint:'初中重点在月夜与“闲人”的意味；高中可讨论不同作品的转折和张力。展签任务借鉴项目化课例，材料组合与缩短课时由本站设计。',extend:'课后增加一篇本站作品；用它检验原有展签，必要时改写人物概括。'}
];
function teachingSourceHtml(ids){return ids.map(id=>teachingSources.find(s=>s.id===id)).filter(Boolean).map(s=>`<article class="teach-source"><a href="${s.url}" target="_blank" rel="noopener noreferrer">${s.title} ↗</a><small>${s.credit} · ${s.date}<br>${s.level}</small><p><b>参考方法：</b>${s.method}</p><p><b>本站改编：</b>${s.adapt}</p></article>`).join('');}
function lessonCTA(poemId){const plan=teachingPlans.find(p=>p.works.some(w=>w[0]===poemId));return plan?`<button class="lesson-cta" data-lesson="${plan.id}"><span>课堂小任务</span><strong>${plan.title}</strong><small>${plan.minutes}分钟 · 有参考来源 ↗</small></button>`:'';}
function bindLessonButtons(){document.querySelectorAll('[data-lesson]').forEach(b=>b.onclick=()=>showLesson(b.dataset.lesson));}
function showTeachingHub(stage='all'){
 if(typeof stop==='function')stop();
 const plans=teachingPlans.filter(p=>stage==='all'||p.stages.includes(stage));
 showModal(`<div class="teaching-hub"><p class="eyebrow">课堂锦囊 · 参考公开课例，重新设计</p><h2>把地图，变成学习任务</h2><p>先读诗，再看地点与影片；最后让学生交出一份有文本依据的作品。以下活动为本站改编，时间为建议用时，可嵌入一课时。</p><div class="teach-principle"><span>01 先读出疑问</span><span>02 在地图定位</span><span>03 用诗句解释</span><span>04 交出小作品</span></div><div class="teach-filters" role="group" aria-label="教学活动学段">${[['all','全部活动'],['初中','初中与衔接'],['高中','高中']].map(([id,label])=>`<button data-teach-stage="${id}" aria-pressed="${id===stage}">${label}</button>`).join('')}</div><div class="teach-cards">${plans.map(p=>`<article><div class="teach-meta">${p.stages.join(' / ')} · ${p.minutes}分钟</div><h3>${p.title}</h3><small>${p.subtitle}</small><p>${p.goal}</p><button data-lesson="${p.id}">展开任务单 →</button></article>`).join('')}</div><details class="teach-references"><summary>查看5项教学参考与本站改编说明</summary><p>仅参考教学方法，不转载整份教案或课件；原文的事实、体裁和解释仍需教材校核。原课例未参与本网站设计，也不表示对本站背书。</p>${teachingSourceHtml(teachingSources.map(s=>s.id))}</details></div>`);
 document.querySelectorAll('[data-teach-stage]').forEach(b=>b.onclick=()=>showTeachingHub(b.dataset.teachStage));bindLessonButtons();
}
function showLesson(id){if(typeof stop==='function')stop();const p=teachingPlans.find(p=>p.id===id);if(!p)return;
 showModal(`<article class="lesson-plan"><button class="teach-back" id="teachBack">← 全部课堂任务</button><p class="eyebrow">${p.stages.join(' / ')} · 建议${p.minutes}分钟 · 本站改编</p><h2>${p.title}</h2><p>${p.subtitle}</p><div class="lesson-goal"><strong>这次学会什么</strong><p>${p.goal}</p><b>主问题</b><p>${p.question}</p></div><div class="lesson-work-links">${p.works.map(([id,title])=>`<a href="index.html?work=${id}">读《${title}》与地图 →</a>`).join('')}</div><ol class="lesson-steps">${p.steps.map(([name,time,task,output])=>`<li><div><h3>${name}</h3><small>${time}</small></div><p>${task}</p><p class="lesson-output"><b>学生交出：</b>${output}</p></li>`).join('')}</ol><section class="lesson-check"><h3>看得见的学习证据</h3>${p.check.map(t=>`<label><input type="checkbox">${t}</label>`).join('')}</section><details class="teacher-hint"><summary>教师点拨与分层建议</summary><p>${p.hint}</p><p>${p.extend}</p><small>以上是讨论支架，不是唯一标准答案。</small></details><div class="lesson-download"><button id="downloadLesson">下载学生任务单（TXT）↓</button><small>可打印或粘贴到班级文档；含作品链接与参考来源。</small></div><section class="lesson-sources"><h3>借鉴了哪些方法？</h3>${teachingSourceHtml(p.sources)}<p class="teach-note">任务表述、地图／影片结合、时间安排和检查要点为本站设计，未声称原教师使用过本站。</p></section></article>`);
 $('teachBack').onclick=()=>showTeachingHub();$('downloadLesson').onclick=()=>downloadLesson(p);
}
function downloadLesson(p){const text=['诗行山河 · 学生任务单',p.title,p.subtitle,`建议用时：${p.minutes}分钟`,`学习目标：${p.goal}`,`主问题：${p.question}`,'',...p.steps.flatMap(([n,t,task,out],i)=>[`${i+1}. ${n}（${t}）`,task,`交付：${out}`,'我的记录：________________________','']), '自查：',...p.check.map(t=>'□ '+t),'','作品与地图：',...p.works.map(([id,title])=>title+' '+new URL('index.html?work='+id,location.href).href),'','参考方法来源（本站改编，非原教案复制）：',...p.sources.map(id=>{const s=teachingSources.find(s=>s.id===id);return s.title+' — '+s.credit+'\n'+s.url;})].join('\n');const url=URL.createObjectURL(new Blob(['\ufeff'+text],{type:'text/plain;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download=p.title+'-学生任务单.txt';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
